/**
 * Bundles the MCP skill tools (`src/skills/mcp.ts` and every skill it imports) into
 * `tools/quadra-mcp/skills.mjs`, so the stdio server runs under bare `node` with no build step
 * on the user's machine. `npm run build:mcp` writes it; `tests/mcp.test.ts` rebuilds it in
 * memory and fails when the checked-in file is stale — a generated file nobody regenerates is
 * the drift this repo keeps finding in hand-kept copies.
 *
 * esbuild is Vite's own bundler (already installed with it); it reads the `@/*` path alias from
 * tsconfig.json. Deterministic: same source, same esbuild, same bytes.
 */
import { build } from "esbuild";
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const OUT = resolve(ROOT, "tools/quadra-mcp/skills.mjs");

const BANNER =
  "// GENERATED by scripts/build-mcp.mjs from src/skills/mcp.ts — do not edit.\n" +
  "// Regenerate with `npm run build:mcp`; tests/mcp.test.ts fails while this is stale.";

/** The bundle's text. */
export async function bundleMcp() {
  const result = await build({
    entryPoints: [resolve(ROOT, "src/skills/mcp.ts")],
    bundle: true,
    format: "esm",
    platform: "node",
    target: "node18",
    write: false,
    legalComments: "none",
    banner: { js: BANNER },
    tsconfig: resolve(ROOT, "tsconfig.json"),
    logLevel: "silent",
  });
  return result.outputFiles[0].text;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUT, await bundleMcp());
  console.log(`wrote ${OUT.replace(`${ROOT}/`, "")}`);
}
